DDL = "\nCREATE TABLE cehub_ai.ai_issue_generation_bindings (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\trequested_by_user_id UUID NOT NULL, \n\tevent_row_id BIGINT NOT NULL, \n\tsource_digest VARCHAR(64) NOT NULL, \n\tpolicy_id UUID, \n\tprincipal_id UUID, \n\tscope_revision_id UUID, \n\tcapture_kind VARCHAR(24) NOT NULL, \n\treason_code VARCHAR(80) NOT NULL, \n\tsnapshot JSONB NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_ai_issue_generation_bindings PRIMARY KEY (id), \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_projects FOREIGN KEY(tenant_id, project_id) REFERENCES cehub_project.projects (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_agent_runs FOREIGN KEY(tenant_id, run_id) REFERENCES cehub_ai.agent_runs (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_users FOREIGN KEY(tenant_id, requested_by_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_events FOREIGN KEY(tenant_id, event_row_id) REFERENCES cehub_event.events (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_ai_write_policies FOREIGN KEY(tenant_id, policy_id) REFERENCES cehub_ai.ai_write_policies (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_ai_principals FOREIGN KEY(tenant_id, principal_id) REFERENCES cehub_ai.ai_principals (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_generation_bindings_tenant_id_ai_write_scop_5280 FOREIGN KEY(tenant_id, project_id, scope_revision_id) REFERENCES cehub_ai.ai_write_scope_revisions (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_issue_generation_binding_run UNIQUE (tenant_id, run_id), \n\tCONSTRAINT uq_issue_generation_binding_scope UNIQUE (tenant_id, project_id, id), \n\tCONSTRAINT ck_ai_issue_generation_bindings_shape CHECK ((capture_kind IN ('evidence_only','trial_candidate') AND event_row_id>0 AND source_digest ~ '^[a-f0-9]{64}$' AND btrim(reason_code)<>'' AND jsonb_typeof(snapshot)='object' AND snapshot->>'version'='event-issue-generation-binding-v1' AND snapshot->>'operation_key'='event.issue.create') IS TRUE), \n\tCONSTRAINT ck_ai_issue_generation_bindings_trial_binding CHECK (capture_kind<>'trial_candidate' OR (policy_id IS NOT NULL AND principal_id IS NOT NULL AND scope_revision_id IS NOT NULL))\n)\n\n;\n\nCREATE TABLE cehub_ai.ai_issue_proposal_reviews (\n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\trun_id UUID NOT NULL, \n\tresult_id UUID NOT NULL, \n\tactor_user_id UUID NOT NULL, \n\tversion INTEGER NOT NULL, \n\taction VARCHAR(16) NOT NULL, \n\treason TEXT NOT NULL, \n\trequest_id UUID NOT NULL, \n\trequest_digest VARCHAR(64) NOT NULL, \n\toutput_event_row_id BIGINT NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tCONSTRAINT pk_ai_issue_proposal_reviews PRIMARY KEY (id), \n\tCONSTRAINT fk_ai_issue_proposal_reviews_tenant_id_projects FOREIGN KEY(tenant_id, project_id) REFERENCES cehub_project.projects (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_proposal_reviews_tenant_id_agent_runs FOREIGN KEY(tenant_id, run_id) REFERENCES cehub_ai.agent_runs (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_proposal_reviews_tenant_id_ai_issue_event_results FOREIGN KEY(tenant_id, project_id, result_id) REFERENCES cehub_ai.ai_issue_event_results (tenant_id, project_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_proposal_reviews_tenant_id_users FOREIGN KEY(tenant_id, actor_user_id) REFERENCES cehub_core.users (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_ai_issue_proposal_reviews_tenant_id_events FOREIGN KEY(tenant_id, output_event_row_id) REFERENCES cehub_event.events (tenant_id, id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_issue_proposal_review_version UNIQUE (tenant_id, result_id, version), \n\tCONSTRAINT uq_issue_proposal_review_request UNIQUE (tenant_id, actor_user_id, request_id), \n\tCONSTRAINT ck_ai_issue_proposal_reviews_shape CHECK (version>0 AND action IN ('decline','reopen') AND btrim(reason)<>'' AND request_digest ~ '^[a-f0-9]{64}$')\n)\n\n;"
GUARDS = "CREATE FUNCTION cehub_ai.guard_issue_generation_binding() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE r cehub_ai.agent_runs%ROWTYPE; p cehub_ai.ai_write_policies%ROWTYPE;\n s cehub_ai.ai_write_scope_revisions%ROWTYPE; principal cehub_ai.ai_principals%ROWTYPE;\n expected_reason text;\nBEGIN\n SELECT * INTO r FROM cehub_ai.agent_runs WHERE tenant_id=NEW.tenant_id AND id=NEW.run_id;\n IF NOT FOUND OR r.project_id<>NEW.project_id OR r.requested_by_user_id<>NEW.requested_by_user_id\n  OR r.context_version<>'event-issue-request-v1' OR r.status<>'running'\n  OR r.created_at<>NEW.created_at OR r.created_at<transaction_timestamp()\n  OR NOT EXISTS(SELECT 1 FROM cehub_ai.agent_runs WHERE id=r.id AND xmin=pg_current_xact_id()::text::xid)\n  OR (r.run_context->'issue_event_source'->>'event_row_id') IS DISTINCT FROM NEW.event_row_id::text\n  OR (r.run_context->'issue_event_source'->>'source_digest') IS DISTINCT FROM NEW.source_digest\n THEN RAISE EXCEPTION 'Generation binding requires its newly created original run'; END IF;\n IF ((NEW.snapshot->>'tenant_id'=NEW.tenant_id::text AND NEW.snapshot->>'project_id'=NEW.project_id::text\n  AND NEW.snapshot->>'run_id'=NEW.run_id::text AND NEW.snapshot->>'request_id'=r.request_id\n  AND NEW.snapshot->>'requested_by_user_id'=NEW.requested_by_user_id::text\n  AND NEW.snapshot->>'event_row_id'=NEW.event_row_id::text AND NEW.snapshot->>'source_digest'=NEW.source_digest\n  AND NEW.snapshot->>'run_version'=r.context_version AND (NEW.snapshot->>'run_created_at')::timestamptz=r.created_at\n  AND NEW.snapshot->>'source_key'=r.run_context->'issue_event_source'->>'source_key'\n  AND NEW.snapshot->>'source_kind'=r.run_context->'issue_event_source'->>'source_kind'\n  AND NEW.snapshot->>'event_id'=r.run_context->'issue_event_source'->>'event_id'\n  AND NEW.snapshot->>'rollout' IN ('disabled','shadow','live') AND jsonb_typeof(NEW.snapshot->'trial_ready')='boolean')) IS NOT TRUE\n THEN RAISE EXCEPTION 'Generation snapshot must match the original request'; END IF;\n SELECT * INTO p FROM cehub_ai.ai_write_policies WHERE tenant_id=NEW.tenant_id ORDER BY revision DESC LIMIT 1;\n SELECT * INTO s FROM cehub_ai.ai_write_scope_revisions WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id\n  AND operation_key='event.issue.create' ORDER BY revision DESC LIMIT 1;\n IF p.id IS NOT NULL THEN SELECT * INTO principal FROM cehub_ai.ai_principals WHERE tenant_id=NEW.tenant_id AND id=p.principal_id; END IF;\n IF NEW.policy_id IS DISTINCT FROM p.id OR NEW.principal_id IS DISTINCT FROM principal.id\n  OR NEW.scope_revision_id IS DISTINCT FROM s.id THEN RAISE EXCEPTION 'Generation controls must be the current originals'; END IF;\n IF p.id IS NULL THEN\n  IF NEW.snapshot->'policy' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Missing policy must remain unknown'; END IF;\n ELSE\n  IF (NEW.snapshot->'policy'->>'id'=p.id::text AND NEW.snapshot->'policy'->>'principal_id'=p.principal_id::text\n   AND NEW.snapshot->'policy'->>'revision'=p.revision::text AND NEW.snapshot->'policy'->>'mode'=p.mode\n   AND NEW.snapshot->'policy'->>'contract_version'=p.contract_version\n   AND NEW.snapshot->'policy'->>'operation_key'='event.issue.create'\n   AND NEW.snapshot->'policy'->'operation_setting'=coalesce(p.operation_settings->'event.issue.create','null'::jsonb)) IS NOT TRUE\n   THEN RAISE EXCEPTION 'Original policy snapshot mismatch'; END IF;\n END IF;\n IF s.id IS NULL THEN\n  IF NEW.snapshot->'scope' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Missing scope must remain unknown'; END IF;\n ELSE\n  IF (NEW.snapshot->'scope'->>'id'=s.id::text AND NEW.snapshot->'scope'->>'revision'=s.revision::text\n   AND NEW.snapshot->'scope'->>'principal_id'=s.principal_id::text AND NEW.snapshot->'scope'->'enabled'=to_jsonb(s.enabled)\n   AND NEW.snapshot->'scope'->>'operation_key'=s.operation_key) IS NOT TRUE THEN RAISE EXCEPTION 'Original scope snapshot mismatch'; END IF;\n END IF;\n IF principal.id IS NULL THEN\n  IF NEW.snapshot->'principal' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'Missing principal must remain unknown'; END IF;\n ELSE\n  IF (NEW.snapshot->'principal'->>'id'=principal.id::text AND NEW.snapshot->'principal'->>'principal_key'=principal.principal_key\n   AND NEW.snapshot->'principal'->>'principal_kind'=principal.principal_kind AND NEW.snapshot->'principal'->>'display_name'=principal.display_name) IS NOT TRUE\n   THEN RAISE EXCEPTION 'Original principal snapshot mismatch'; END IF;\n END IF;\n expected_reason:=CASE WHEN p.id IS NULL THEN 'policy_missing'\n  WHEN p.contract_version<>'dc11-write-policy.v1' THEN 'policy_contract_unknown'\n  WHEN p.mode<>'tiered' THEN 'policy_not_tiered'\n  WHEN coalesce(p.operation_settings->'event.issue.create'->>'mode','disabled') NOT IN ('confirm','automatic') THEN 'operation_not_enabled'\n  WHEN principal.id IS NULL OR principal.principal_kind<>'ai' OR principal.principal_key<>'pdos-agent' THEN 'principal_unverified'\n  WHEN s.id IS NULL OR NOT s.enabled OR s.principal_id<>principal.id THEN 'scope_not_enabled'\n  WHEN NEW.snapshot->>'rollout'<>'live' THEN 'rollout_not_live'\n  WHEN NEW.snapshot->>'trial_ready'<>'true' THEN 'trial_not_ready' ELSE 'trial_candidate' END;\n IF NEW.reason_code<>expected_reason OR (NEW.capture_kind='trial_candidate')<>(expected_reason='trial_candidate')\n THEN RAISE EXCEPTION 'Generation evidence cannot promote trial eligibility'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_issue_generation_binding BEFORE INSERT ON cehub_ai.ai_issue_generation_bindings\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.guard_issue_generation_binding();\nCREATE TRIGGER immutable_issue_generation_binding BEFORE UPDATE OR DELETE ON cehub_ai.ai_issue_generation_bindings\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history();\n\nCREATE FUNCTION cehub_ai.guard_issue_proposal_review() RETURNS trigger LANGUAGE plpgsql AS $$\nDECLARE prior cehub_ai.ai_issue_proposal_reviews%ROWTYPE; result cehub_ai.ai_issue_event_results%ROWTYPE;\nBEGIN\n SELECT * INTO result FROM cehub_ai.ai_issue_event_results WHERE tenant_id=NEW.tenant_id AND project_id=NEW.project_id AND id=NEW.result_id;\n IF NOT FOUND OR result.run_id<>NEW.run_id OR NOT EXISTS(SELECT 1 FROM cehub_ai.agent_runs r\n  WHERE r.tenant_id=NEW.tenant_id AND r.project_id=NEW.project_id AND r.id=NEW.run_id AND r.status='succeeded'\n   AND r.context_version='event-issue-request-v1' AND r.run_context->>'issue_event_result_id'=NEW.result_id::text)\n  OR EXISTS(SELECT 1 FROM cehub_ai.ai_issue_applications a WHERE a.tenant_id=NEW.tenant_id AND a.project_id=NEW.project_id\n    AND a.source_key=result.source_snapshot->>'source_key')\n THEN RAISE EXCEPTION 'Review requires an original unapplied proposal'; END IF;\n SELECT * INTO prior FROM cehub_ai.ai_issue_proposal_reviews WHERE tenant_id=NEW.tenant_id AND result_id=NEW.result_id ORDER BY version DESC LIMIT 1;\n IF NEW.version<>coalesce(prior.version,0)+1 OR NEW.action<>(CASE WHEN prior.action='decline' THEN 'reopen' ELSE 'decline' END)\n THEN RAISE EXCEPTION 'Review must extend the original decision history'; END IF;\n IF NOT EXISTS(SELECT 1 FROM cehub_event.events e JOIN cehub_audit.audit_log a\n  ON a.tenant_id=e.tenant_id AND a.project_id=e.project_id AND a.event_id=e.event_id AND a.entity_id=e.entity_id AND a.timestamp=e.timestamp\n  WHERE e.tenant_id=NEW.tenant_id AND e.project_id=NEW.project_id AND e.id=NEW.output_event_row_id\n   AND e.entity_id=NEW.id AND e.event_type='AI_ISSUE_PROPOSAL_REVIEW_RECORDED' AND e.source='ai_issue_review_service'\n   AND e.payload->>'review_id'=NEW.id::text AND e.payload->>'result_id'=NEW.result_id::text\n   AND e.payload->>'action'=NEW.action AND e.payload->>'version'=NEW.version::text\n   AND a.action='ai_issue.proposal_review' AND a.actor_user_id=NEW.actor_user_id\n   AND a.after_snapshot->>'reason'=NEW.reason)\n THEN RAISE EXCEPTION 'Review requires its exact named event and audit'; END IF;\n RETURN NEW;\nEND $$;\nCREATE TRIGGER guard_issue_proposal_review BEFORE INSERT ON cehub_ai.ai_issue_proposal_reviews\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.guard_issue_proposal_review();\nCREATE TRIGGER immutable_issue_proposal_review BEFORE UPDATE OR DELETE ON cehub_ai.ai_issue_proposal_reviews\n FOR EACH ROW EXECUTE FUNCTION cehub_ai.protect_checkpoint_history();\nREVOKE ALL ON cehub_ai.ai_issue_generation_bindings,cehub_ai.ai_issue_proposal_reviews FROM PUBLIC;\nDO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='pdos_agent') THEN\n REVOKE ALL ON cehub_ai.ai_issue_generation_bindings,cehub_ai.ai_issue_proposal_reviews FROM pdos_agent; END IF; END $$;\n"


def upgrade() -> None:
    op.execute(DDL)
